class WebhookEndpointCreate(BaseModel):
    url: HttpUrl
    subscribed_events: List[str]
    organization_id: Optional[int] = None

    @model_validator(mode="after")
    def validate_events(self) -> "WebhookEndpointCreate":
        allowed = {"order.paid", "order.refunded", "customer.created"}
        if not set(self.subscribed_events).issubset(allowed):
            raise ValueError("Invalid event topic included")
        return self

@router.post("/api/v2/webhooks")
def register_webhook(
    payload: WebhookEndpointCreate,
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    if payload.organization_id is not None and payload.organization_id != user.organization_id:
        if not user.is_superuser:
            raise HTTPException(status_code=403, detail="Cannot register webhooks for another organization")
    target_org = payload.organization_id if (payload.organization_id and user.is_superuser) else user.organization_id
    endpoint = WebhookSubscription(
        url=str(payload.url),
        events=payload.subscribed_events,
        organization_id=target_org
    )
    db.add(endpoint)
    db.commit()
    return {"id": endpoint.id, "organization_id": target_org}
